using FixFinder.Core.Analysis.Frontends;
using FixFinder.Core.Analysis.Ir;
using FixFinder.Core.Analysis.Recognition;

namespace FixFinder.Tests;

/// <summary>
/// Recognising the algorithm a function is written as, from its shape: a binary search, a linear search, a bubble sort, a
/// selection sort, an insertion sort, a search for the largest or smallest item, a prime test, a leap-year test, a factorial and a reversal, each written as it is usually written
/// in Python, Java, JavaScript, C#, C, C++ and Go - and in Java over lists too - and each said in the code's own names: the
/// sentences are those the recognition gave for these programs. Code with a similar shape that is none of them - a check
/// that a list is in order, a times table, a count, a count of digits, a square root found by halving, the days in
/// February worked out by the leap-year rule, a test of 4 alone, an even test, a product of a list's items, a power, a
/// product of every second number, a sum of the numbers up to n, a product of the numbers from n up to 10, a partition
/// swapping from both ends, a rotation and a copy shifted by one - is
/// recognised as nothing.
/// </summary>
public class AlgorithmRecognitionTests : IDisposable
{
    private readonly TempFolder _temp = new();

    public void Dispose()
    {
        _temp.Dispose();
        GC.SuppressFinalize(this);
    }

    /// <summary>The program read by its own language's reader; null when this computer has no Python, JDK or Go to read it with.</summary>
    private async Task<IrProgram?> ReadAsync(string fileName, string code)
    {
        var path = Path.Combine(_temp.Path, fileName);
        await File.WriteAllTextAsync(path, code);

        return Path.GetExtension(fileName).ToLowerInvariant() switch
        {
            ".py" => PythonFrontend.FindInterpreter() is { } python ? await PythonFrontend.ReadAsync([path], python) : null,
            ".java" => JavaFrontend.FindTools() is { } tools ? await JavaFrontend.ReadAsync([path], tools.Javac, tools.Java) : null,
            ".go" => GoFrontend.FindGo(path) is { } go ? await GoFrontend.ReadAsync([path], go) : null,
            ".js" => await JavaScriptFrontend.ReadAsync([path]),
            ".cs" => await CSharpFrontend.ReadAsync([path]),
            _ => await CFrontend.ReadAsync([path]),
        };
    }

