    [InlineData("Fact.cs", "using System;\n\nclass Fact\n{\n    static long Factorial(int n)\n    {\n        if (n <= 1)\n        {\n            return 1;\n        }\n        return n * Factorial(n - 1);\n    }\n\n    static void Main()\n    {\n        Console.WriteLine(Factorial(5));\n    }\n}\n",
