    [InlineData("Rev.cs", "using System;\n\nclass Rev\n{\n    static void Reverse(int[] items)\n    {\n        for (int i = 0; i < items.Length / 2; i++)\n        {\n            (items[i], items[items.Length - 1 - i]) = (items[items.Length - 1 - i], items[i]);\n        }\n    }\n\n    static void Main()\n    {\n        int[] items = { 1, 2, 3 };\n        Reverse(items);\n        Console.WriteLine(string.Join(\", \", items));\n    }\n}\n",
